	if json.Unmarshal(data, &k) != nil {
		return Keep{}
	}
	return k
}

func syncDir(store string) error {
	d, err := os.Open(store)
	if err != nil { return err }
	defer d.Close()
	Fence(d)
	return nil
}

// WriteKeep atomically installs a fully fenced coordination record.
func WriteKeep(store string, keep Keep) error {
	tmp := PathFor(store) + ".tmp"
	f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0644)
	if err != nil { return err }
	if err = json.NewEncoder(f).Encode(keep); err != nil { f.Close(); return err }
	Fence(f)
	if err = f.Close(); err != nil { return err }
	if err = os.Rename(tmp, PathFor(store)); err != nil { return err }
	return syncDir(store)
}
